--   sms_id_int:                integer                    
--   sms_number:                varchar                    
--   letter_id:                 integer                    
--   CONSTRAINT:                mail_notification_notification_partner_or_email_required CHECK ((((notification_type)::text <> 'email'::text) OR (failure_type IS) OR (res_partner_id IS) OR ((COALESCE(mail_email_address, ''::varchar))::text <> ''::text))) NOT NULL
--   CONSTRAINT:                mail_notification_notification_partner_required CHECK ((((notification_type)::text <> 'inbox'::text) OR (res_partner_id IS))) NOT NULL
-- ----------------------------------------------------------------------

